import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
INF = 10**9
d = [[INF] * c for _ in range(r)]
if g[0][0] == 0:
    d[0][0] = 1
changed = True
while changed:
    changed = False
    for i in range(r):
        for j in range(c):
            if g[i][j] != 0:
                continue
            for di in (-1, 0, 1):
                for dj in (-1, 0, 1):
                    a, b = i + di, j + dj
                    if (di or dj) and 0 <= a < r and 0 <= b < c and d[a][b] + 1 < d[i][j]:
                        d[i][j] = d[a][b] + 1
                        changed = True
print(d[r - 1][c - 1] if d[r - 1][c - 1] < INF and g[r - 1][c - 1] == 0 else -1)

